import React from 'react';
import { Link } from 'react-router-dom';
import './NavBar.css';

function NavBar() {
  return (
    <nav className="navbar">
      <h2 className="nav-title">Food Truck Vendor Application</h2>
      <ul className="nav-menu">
        <li><Link to="/" className="nav-link">Home</Link></li>
        <li><Link to="/getAllVendors" className="nav-link">Vendor Details</Link></li>
      </ul>
    </nav>
  );
}

export default NavBar;
